package org.pms.silverocean.controller;

import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.pms.silverocean.common.ResponseCode;import org.pms.silverocean.controller.wrappers.ResponseDTO;import org.pms.silverocean.service.I18NService;import org.pms.silverocean.service.affiliate.AffiliateModels;import org.pms.silverocean.service.affiliate.AffiliateService;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;

@RestController @RequestMapping("/affiliate") @RequiredArgsConstructor
public class AffiliateController {private final AffiliateService service;private final I18NService i18n;private ResponseEntity<ResponseDTO> ok(Object value){return ResponseEntity.ok(new ResponseDTO(true, ResponseCode.GENERAL_SUCCESS.getCode(),i18n.getLocalizedMessage(ResponseCode.GENERAL_SUCCESS),value));}@GetMapping("/public/{code}")@PreAuthorize("permitAll()")public ResponseEntity<ResponseDTO> resolve(@PathVariable String code){service.resolve(code);return ok(new AffiliateModels.PublicReferral(true));}@GetMapping("/dashboard")@PreAuthorize("hasAnyRole('AFFILIATE','SUPER_ADMIN')")public ResponseEntity<ResponseDTO> dashboard(){return ok(service.dashboard());}@PutMapping("/payout-account")@PreAuthorize("hasAnyRole('AFFILIATE','SUPER_ADMIN')")public ResponseEntity<ResponseDTO> account(@RequestBody @Valid AffiliateModels.PayoutAccount request){return ok(service.setPayoutAccount(request.paymentAccountId()));}@PostMapping("/payout")@PreAuthorize("hasAnyRole('AFFILIATE','SUPER_ADMIN')")public ResponseEntity<ResponseDTO> payout(){return ok(service.requestPayout());}@GetMapping("/admin/payouts")@PreAuthorize("hasRole('SUPER_ADMIN')")public ResponseEntity<ResponseDTO> payouts(){return ok(service.adminPayouts());}@PutMapping("/admin/payouts/{id}")@PreAuthorize("hasRole('SUPER_ADMIN')")public ResponseEntity<ResponseDTO> decide(@PathVariable long id,@RequestBody @Valid AffiliateModels.PayoutDecision request){return ok(service.decidePayout(id,request));}}
